"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/search-input.css";
import { MagnifyingGlass, X } from "@phosphor-icons/react";
import { forwardRef, useId, useState, type InputHTMLAttributes } from "react";
import { cn } from "../../lib/cn";

export type SearchInputProps = Omit<InputHTMLAttributes<HTMLInputElement>, "type"> & {
  label?: string;
  loading?: boolean;
  onClear?: () => void;
  shortcut?: string;
};

export const SearchInput = forwardRef<HTMLInputElement, SearchInputProps>(function SearchInput({ id: providedId, label = "Search", loading, onClear, shortcut, className, value, defaultValue, onChange, ...props }, ref) {
  const generatedId = useId();
  const id = providedId ?? generatedId;
  const controlled = value !== undefined;
  const [uncontrolledValue, setUncontrolledValue] = useState(() => String(defaultValue ?? ""));
  const currentValue = controlled ? String(value ?? "") : uncontrolledValue;
  const hasValue = currentValue.length > 0;
  return (
    <div className="whatiuse-search-field">
      <label className="whatiuse-sr-only" htmlFor={id}>{label}</label>
      <div className={cn("whatiuse-search", className)} data-loading={loading || undefined}>
        {loading ? <span className="whatiuse-spinner whatiuse-search__spinner" aria-hidden="true" /> : <MagnifyingGlass className="whatiuse-search__icon" aria-hidden="true" />}
        <input
          ref={ref}
          id={id}
          type="search"
          value={controlled ? value : uncontrolledValue}
          aria-busy={loading || undefined}
          onChange={(event) => {
            if (!controlled) setUncontrolledValue(event.currentTarget.value);
            onChange?.(event);
          }}
          {...props}
        />
        {hasValue && onClear ? <button type="button" aria-label="Clear search" onClick={() => { if (!controlled) setUncontrolledValue(""); onClear(); }}><X /></button> : shortcut ? <kbd>{shortcut}</kbd> : null}
      </div>
    </div>
  );
});

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-search { display: flex; width: 100%; min-width: 220px; height: 32px; align-items: center; gap: 7px; padding: 0 8px; border: 1px solid var(--whatiuse-border); border-radius: var(--whatiuse-radius-sm); background: var(--whatiuse-control-surface); box-shadow: var(--whatiuse-shadow-control); transition: border-color var(--whatiuse-hover-duration) ease, box-shadow var(--whatiuse-hover-duration) ease; }

.whatiuse-search__icon { width: 14px; height: 14px; color: var(--whatiuse-ink-tertiary); }

.whatiuse-search__spinner { width: 13px; height: 13px; }

.whatiuse-search input { min-width: 0; height: 100%; flex: 1; border: 0; outline: 0; background: transparent; color: var(--whatiuse-ink); font: inherit; font-size: var(--whatiuse-type-ui); -webkit-appearance: none; appearance: none; }

.whatiuse-search input::-webkit-search-cancel-button { display: none; }

.whatiuse-search input::placeholder { color: var(--whatiuse-ink-tertiary); }

.whatiuse-search button { display: grid; width: 24px; height: 24px; flex: 0 0 24px; place-items: center; border: 0; border-radius: 5px; background: transparent; color: var(--whatiuse-ink-tertiary); cursor: pointer; }

.whatiuse-search button svg { width: 12px; height: 12px; }

.whatiuse-search kbd { display: inline-flex; flex: 0 0 auto; align-items: center; justify-content: center; color: var(--whatiuse-ink-tertiary); font-size: 10px; line-height: 1; white-space: nowrap; }

@media (hover: hover) and (pointer: fine) {
.whatiuse-search button:hover { background: var(--whatiuse-hover); color: var(--whatiuse-ink); }

.whatiuse-search:hover { border-color: var(--whatiuse-border-strong); }
}

.whatiuse-search input:focus-visible { outline: 0; }

.whatiuse-spinner { width: 13px; height: 13px; border: 1.5px solid currentColor; border-right-color: transparent; border-radius: 50%; animation: whatiuse-spin 0.75s linear infinite; }

.whatiuse-search button { transition: color var(--whatiuse-hover-duration), background-color var(--whatiuse-hover-duration), transform var(--whatiuse-press-duration) var(--whatiuse-ease-out); }

.whatiuse-search button:active { transform: scale(.96); }

@media (prefers-reduced-motion: reduce) {
.whatiuse-search button:active { transform: none; }

.whatiuse-spinner { animation-duration: 2.4s; }
}

@keyframes whatiuse-spin { to { transform: rotate(360deg); } }
}
